<script setup lang="ts">
import { formatDate } from '@/utils/formatTime'
import * as BoxunProjectInfoApi from './BoxunProjectInfoApi'

type BoxunProjectInfoDetail = Awaited<ReturnType<typeof BoxunProjectInfoApi.getBoxunProjectInfo>>
type EntityId = string | number

defineOptions({ name: 'BoxunProjectInfoDetail' })

const dialogVisible = ref(false)
const loading = ref(false)
const detail = ref<BoxunProjectInfoDetail>()

const open = async (id: EntityId) => {
  detail.value = undefined
  dialogVisible.value = true
  loading.value = true
  try {
    detail.value = await BoxunProjectInfoApi.getBoxunProjectInfo(id)
  } finally {
    loading.value = false
  }
}
defineExpose({ open })
</script>
